function makeCirclePoints(cx: number, cy: number, r: number, steps = 36): BezierPoint[] {
  const pts: BezierPoint[] = [];
  for (let i = 0; i <= steps; i++) {
    const th = (i / steps) * Math.PI * 2;
    pts.push({
      x: Number((cx + Math.cos(th) * r).toFixed(2)),
      y: Number((cy + Math.sin(th) * r).toFixed(2)),
      pressure: 0.65,
    });
  }
  return pts;
}

function makeRectPoints(x1: number, y1: number, x2: number, y2: number): BezierPoint[] {
  return [
    { x: x1, y: y1, pressure: 0.65 },
    { x: x2, y: y1, pressure: 0.65 },
    { x: x2, y: y2, pressure: 0.65 },
    { x: x1, y: y2, pressure: 0.65 },
    { x: x1, y: y1, pressure: 0.65 },
  ];
}

